package com.singtel.promotionservice;import java.util.*;import com.singtel.platformcommon.DomainError;
public final class Lifecycle{public enum Status{DRAFT,PENDING_APPROVAL,APPROVED,SCHEDULED,ACTIVE,PAUSED,EXPIRED,RETIRED}private static final Map<Status,Set<Status>> ALLOWED=Map.of(Status.DRAFT,Set.of(Status.PENDING_APPROVAL),Status.PENDING_APPROVAL,Set.of(Status.APPROVED,Status.DRAFT),Status.APPROVED,Set.of(Status.SCHEDULED,Status.ACTIVE),Status.SCHEDULED,Set.of(Status.ACTIVE,Status.RETIRED),Status.ACTIVE,Set.of(Status.PAUSED,Status.EXPIRED),Status.PAUSED,Set.of(Status.ACTIVE,Status.RETIRED),Status.EXPIRED,Set.of(Status.RETIRED),Status.RETIRED,Set.of());public static void check(Status current,Status next,String creator,String actor){if(!ALLOWED.get(current).contains(next))throw DomainError.conflict("INVALID_TRANSITION","Cannot transition from "+current+" to "+next);if(next==Status.APPROVED&&Objects.equals(creator,actor))throw DomainError.invalid("SELF_APPROVAL","Creator cannot approve their own campaign");}}
